refsection.programlisting:
// GF(16) con el polinomio primitivo por defecto 1 + x + x^4
F = gf_create_field(2, 4);
F(3)              // [1 1 0 0 1]
F(4)(1:6, :)      // 0, 1, alpha, alpha^2, alpha^3, alpha^4 = 1 + alpha

// El mismo campo construido con otro polinomio primitivo: 1 + x^3 + x^4
G = gf_create_field(2, 4, [1 0 0 1 1]);

// 1 + x + x^2 + x^3 + x^4 es irreducible pero no primitivo
try
    gf_create_field(2, 4, [1 1 1 1 1]);
catch
    disp(lasterror())
end

// El campo primo GF(7); su polinomio por defecto es x - 3 = x + 4
P = gf_create_field(7, 1);
P(3)              // [4 1]
